import os, filecmp, difflib

BUG = "/workspace/buggy"
FIX = "/workspace/fixed"

pyfiles = {}
for base in (BUG, FIX):
    fs = set()
    for dirpath, dirnames, filenames in os.walk(base):
        if ".git" in dirpath:
            continue
        for fn in filenames:
            if fn.endswith(".py"):
                fs.add(os.path.relpath(os.path.join(dirpath, fn), base))
    pyfiles[base] = fs

diffs = []
for rel in sorted(pyfiles[BUG] | pyfiles[FIX]):
    bp = os.path.join(BUG, rel)
    fp = os.path.join(FIX, rel)
    bs = open(bp, encoding="utf-8", errors="ignore").read() if os.path.exists(bp) else ""
    fs = open(fp, encoding="utf-8", errors="ignore").read() if os.path.exists(fp) else ""
    if bs != fs:
        d = "".join(difflib.unified_diff(bs.splitlines(True), fs.splitlines(True),
                                          fromfile="buggy/" + rel, tofile="fixed/" + rel))
        diffs.append(d)
probe("diff_files", diffs)

# Also search for the distinctive scenario text
matches = []
for base in (BUG, FIX):
    for dirpath, dirnames, filenames in os.walk(base):
        if ".git" in dirpath:
            continue
        for fn in filenames:
            if not (fn.endswith(".py") or fn.endswith(".rst") or fn.endswith(".md")):
                continue
            p = os.path.join(dirpath, fn)
            try:
                s = open(p, encoding="utf-8", errors="ignore").read()
            except Exception:
                continue
            for i, line in enumerate(s.splitlines()):
                if "[-1, 1, 1]" in line or "fill_value=pd.NA" in line:
                    matches.append(f"{p}:{i+1}: {line.strip()}")
probe("matches", matches)

